use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
    removed: bool,
}

impl Tree {
    fn new() -> Tree {
        Tree { keys: [], lefts: [], rights: [], root: -1, removed: false }
    }

    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur as usize]
            if x == k { return true }
            if x < k { cur = self.lefts[cur as usize] } else { cur = self.rights[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.keys.len() as int
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root == -1 {
            self.root = id
            return
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.lefts[cur as usize]
                if l == -1 {
                    self.lefts[cur as usize] = id
                    return
                }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r == -1 {
                    self.rights[cur as usize] = id
                    return
                }
                cur = r
            }
        }
    }

    fn min_node(self, n: int) -> int {
        let mut cur = n
        while self.lefts[cur as usize] != -1 {
            cur = self.lefts[cur as usize]
        }
        cur
    }

    fn max_node(self, n: int) -> int {
        let mut cur = n
        while self.rights[cur as usize] != -1 {
            cur = self.rights[cur as usize]
        }
        cur
    }

    fn remove_at(self, node: int, x: int) -> int {
        if node == -1 { return -1 }
        let k = self.keys[node as usize]
        if x < k {
            let l = self.remove_at(self.lefts[node as usize], x)
            self.lefts[node as usize] = l
            return node
        }
        if x > k {
            let r = self.remove_at(self.rights[node as usize], x)
            self.rights[node as usize] = r
            return node
        }
        self.removed = true
        let l = self.lefts[node as usize]
        let r = self.rights[node as usize]
        if l == -1 { return r }
        if r == -1 { return l }
        let s = self.min_node(r)
        let sk = self.keys[s as usize]
        self.keys[node as usize] = sk
        let nr = self.remove_at(r, sk)
        self.rights[node as usize] = nr
        node
    }

    fn height_at(self, n: int) -> int {
        if n == -1 { return 0 }
        let a = self.height_at(self.lefts[n as usize])
        let b = self.height_at(self.rights[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int, out: Vec<string>) -> Vec<string> {
        let mut o = out
        if n == -1 { return o }
        o = self.walk(self.lefts[n as usize], o)
        o.push("${self.keys[n as usize]}")
        o = self.walk(self.rights[n as usize], o)
        o
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree::new()
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            t.removed = false
            let r = t.remove_at(t.root, x)
            t.root = r
            if t.removed { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            if t.root == -1 { println("<empty>") } else {
                let o = t.walk(t.root, [])
                println(o.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height_at(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 { println("empty") } else { println("${t.keys[t.min_node(t.root) as usize]}") }
        } else if cmd == "max" {
            if t.root == -1 { println("empty") } else { println("${t.keys[t.max_node(t.root) as usize]}") }
        }
    }
}

